// Vite plugin: writes dist/THIRD_PARTY_NOTICES.txt, the copyright notices and
// license texts of every open-source component that ships in Local Eml.
//
// - npm packages: every package with a module in the output bundle, found from
//   the bundle itself so the list can't drift from what actually ships, plus
//   the font packages that style.css pulls in through @import.
// - Go modules: web/third-party/go-notices.txt, generated by
//   scripts/gen-go-notices.go (the web build has no Go toolchain in CI).
//
// The Go binary embeds dist/, so the file is in the app at
// /THIRD_PARTY_NOTICES.txt (linked from Settings > Attributions), and the
// release workflow attaches the same file to each GitHub release.
import { existsSync, readdirSync, readFileSync, statSync } from 'node:fs'
import { join, relative } from 'node:path'
import type { Plugin } from 'vite'

const root = __dirname
const webRoot = join(root, '..')
const nodeModules = join(webRoot, 'node_modules')

// Shipped through CSS @import (fonts), which never appears as a JS module.
const cssPackages = ['@fontsource/roboto', 'pretendard']

// Pre-built bundles that inline other packages: jszip's browser build
// (dist/jszip.min.js) carries pako, lie, immediate and setimmediate.
const inlined: Record<string, string[]> = {
  jszip: ['pako', 'lie', 'immediate', 'setimmediate'],
}

const noticeFile = /^(licen[cs]e|copying|notice)([.-].*)?$/i

function packageOf(id: string): string | null {
  const i = id.lastIndexOf('/node_modules/')
  if (i < 0) return null
  const parts = id.slice(i + '/node_modules/'.length).split('/')
  return parts[0].startsWith('@') ? `${parts[0]}/${parts[1]}` : parts[0]
}

function read(path: string): string {
  return readFileSync(path, 'utf8').replace(/\r\n/g, '\n').trimEnd()
}

function section(title: string, body: string[]): string {
  return `\n${'='.repeat(80)}\n${title}\n${body.map((b) => `${'-'.repeat(80)}\n${b}\n`).join('')}`
}

function packageNotices(name: string): string {
  const dir = join(nodeModules, name)
  const pkg = JSON.parse(readFileSync(join(dir, 'package.json'), 'utf8'))
  const license = typeof pkg.license === 'string' ? pkg.license : 'see below'
  const body: string[] = []
  for (const f of readdirSync(dir).sort()) {
    if (noticeFile.test(f) && statSync(join(dir, f)).isFile()) body.push(`${f}\n\n${read(join(dir, f))}`)
  }
  // Packages published without a license file (pretendard) get the upstream
  // text from web/third-party/licenses/.
  const fallback = join(root, 'licenses', `${name.replace('/', '__')}.txt`)
  if (body.length === 0 && existsSync(fallback)) body.push(`LICENSE (from upstream)\n\n${read(fallback)}`)
  if (body.length === 0) {
    throw new Error(`third-party-notices: ${name} ships no license file; add web/third-party/licenses/${name.replace('/', '__')}.txt`)
  }
  // rhwp's WASM module carries Rust crates, fonts metrics and vendored code
  // whose notices the package publishes under notices/.
  if (name === '@rhwp/core') {
    const nd = join(dir, 'notices')
    for (const f of walk(nd)) {
      // Skip binaries, machine-readable manifests and patch changelogs.
      if (/\.(pdf|json)$/i.test(f) || /RHWP_PATCHES\.md$/.test(f)) continue
      body.push(`notices/${relative(nd, f)}\n\n${read(f)}`)
    }
  }
  return section(`${pkg.name} ${pkg.version} (${license})`, body)
}

function walk(dir: string): string[] {
  const out: string[] = []
  for (const e of readdirSync(dir, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name))) {
    const p = join(dir, e.name)
    if (e.isDirectory()) out.push(...walk(p))
    else out.push(p)
  }
  return out
}

const header = `Local Eml - third-party notices

Local Eml is free software, licensed under the GNU General Public License v3.0
(https://github.com/hwhang0917/local-eml/blob/main/LICENSE). Its source code
is at https://github.com/hwhang0917/local-eml.

Local Eml includes the open-source components listed below, each under its own
license. Their copyright notices, license texts and NOTICE files follow.

This software is based in part on the work of the Independent JPEG Group.

The HWP viewer (rhwp, https://github.com/edwardkim/rhwp) includes a few
functions under the Mozilla Public License 2.0 in its vendored svg2pdf; their
source code is available from that repository.

Part 1: Web interface (npm packages bundled into the app)
Part 2: Go modules compiled into the local-eml binary
`

export function thirdPartyNotices(): Plugin {
  return {
    name: 'third-party-notices',
    apply: 'build',
    generateBundle(_, bundle) {
      const names = new Set<string>(cssPackages)
      for (const out of Object.values(bundle)) {
        if (out.type !== 'chunk') continue
        for (const id of out.moduleIds ?? Object.keys(out.modules)) {
          const n = packageOf(id.replace(/\\/g, '/'))
          if (n) names.add(n)
        }
      }
      for (const [host, libs] of Object.entries(inlined)) {
        if (names.has(host)) libs.forEach((l) => names.add(l))
      }
      const web = [...names].sort().map(packageNotices).join('')
      const go = read(join(root, 'go-notices.txt'))
      this.emitFile({
        type: 'asset',
        fileName: 'THIRD_PARTY_NOTICES.txt',
        source: `${header}\n\n${'#'.repeat(80)}\nPart 1: Web interface\n${'#'.repeat(80)}\n${web}\n\n${'#'.repeat(80)}\nPart 2: ${go}\n`,
      })
    },
  }
}
